package com.receiptledger.v1;

import android.app.*;import android.graphics.Bitmap;import android.os.Bundle;import android.view.*;import android.widget.*;import com.receiptledger.v1.archive.ReceiptRepository;import com.receiptledger.v1.persistence.ReceiptRecord;import com.receiptledger.v1.ui.ReceiptDisplayFormatter;import java.util.concurrent.*;

public final class ReceiptDetailActivity extends Activity {
    public static final String EXTRA_ID="receipt_id";private final ExecutorService worker=Executors.newSingleThreadExecutor();private ReceiptRepository repository;private LinearLayout content;private TextView status;private Bitmap image;private long generation;
    @Override protected void onCreate(Bundle b){super.onCreate(b);repository=new ReceiptRepository(getApplicationContext());int p=dp(12);ScrollView scroll=new ScrollView(this);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(p,p,p,p);status=new TextView(this);content.addView(status);scroll.addView(content);setContentView(scroll);load();}
    private void load(){String id=getIntent().getStringExtra(EXTRA_ID);if(id==null){finish();return;}long ticket=++generation;status.setText(R.string.detail_loading);worker.execute(()->{ReceiptRecord r=repository.get(id);Bitmap b=repository.loadImage(id,1600);runOnUiThread(()->{if(ticket!=generation){if(b!=null)b.recycle();return;}if(r==null){status.setText(R.string.detail_missing);return;}render(r,b);});});}
    private void render(ReceiptRecord r,Bitmap b){content.removeAllViews();TextView title=new TextView(this);title.setText(R.string.detail_title);title.setTextSize(22);content.addView(title);if(b!=null){image=b;ImageView iv=new ImageView(this);iv.setAdjustViewBounds(true);iv.setScaleType(ImageView.ScaleType.FIT_CENTER);iv.setImageBitmap(b);content.addView(iv,new LinearLayout.LayoutParams(-1,-2));}TextView detail=new TextView(this);detail.setTextIsSelectable(true);detail.setText(ReceiptDisplayFormatter.detail(r));content.addView(detail);Button delete=new Button(this);delete.setText(R.string.delete_receipt);delete.setOnClickListener(v->new AlertDialog.Builder(this).setMessage(R.string.delete_confirm).setNegativeButton(android.R.string.cancel,null).setPositiveButton(R.string.delete_receipt,(d,w)->delete(r.id)).show());content.addView(delete);}
    private void delete(String id){status=null;worker.execute(()->{repository.delete(id);runOnUiThread(this::finish);});}
    @Override protected void onDestroy(){generation++;worker.shutdownNow();if(image!=null&&!image.isRecycled())image.recycle();repository.close();super.onDestroy();}private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}
}
